from __future__ import annotations

import math
from typing import Iterable, List, Tuple


Circle = Tuple[float, float, float]


def _grid_dims(n: int) -> Tuple[int, int]:
    cols = math.ceil(math.sqrt(n))
    rows = (n + cols - 1) // cols
    return rows, cols


def _grid_packing(n: int) -> List[Circle]:
    if n == 1:
        return [(0.5, 0.5, 0.5)]

    rows, cols = _grid_dims(n)
    r = min(1.0 / (2.0 * cols), 1.0 / (2.0 * rows))
    xs = [(j + 0.5) / cols for j in range(cols)]
    ys = [(i + 0.5) / rows for i in range(rows)]

    circles: List[Circle] = []
    for i in range(rows):
        y = ys[i]
        for j in range(cols):
            if len(circles) >= n:
                return circles
            x = xs[j]
            circles.append((x, y, r))
    return circles


def _hex_radius_for_dims(rows: int, cols: int, odd_short: bool) -> float:
    if rows <= 0 or cols <= 0:
        return 0.0
    if rows == 1:
        return 1.0 / (2.0 * cols)
    width_factor = 2.0 * cols - (1.0 if odd_short else 0.0)
    return min(1.0 / width_factor, 1.0 / (2.0 + math.sqrt(3.0) * (rows - 1)))


def _hex_packing(rows: int, cols: int, odd_short: bool, n: int) -> List[Circle]:
    r = _hex_radius_for_dims(rows, cols, odd_short)
    if not (r > 0.0 and math.isfinite(r)):
        return []

    dy = math.sqrt(3.0) * r
    circles: List[Circle] = []
    for i in range(rows):
        offset = r if (i % 2 == 0) else 2.0 * r
        count = cols - 1 if (odd_short and (i % 2 == 1)) else cols
        y = r + i * dy
        for j in range(count):
            x = offset + 2.0 * r * j
            circles.append((x, y, r))
            if len(circles) == n:
                return circles
    return circles if len(circles) == n else []


def _best_hex_packing(n: int) -> List[Circle]:
    if n == 1:
        return [(0.5, 0.5, 0.5)]

    best: List[Circle] = []
    best_r = -1.0

    max_rows = n
    for rows in range(1, max_rows + 1):
        cols = (n + rows - 1) // rows
        for odd_short in (False, True):
            capacity = rows * cols - ((rows // 2) if odd_short else 0)
            if capacity < n:
                continue
            packing = _hex_packing(rows, cols, odd_short, n)
            if not packing:
                continue
            r = packing[0][2]
            if r > best_r:
                best_r = r
                best = packing

    return best


def _validate(circles: List[Circle], n: int) -> List[Circle]:
    if len(circles) != n:
        raise AssertionError("incorrect number of circles")

    for x, y, r in circles:
        if not (r > 0.0 and math.isfinite(x) and math.isfinite(y) and math.isfinite(r)):
            raise AssertionError("non-finite or non-positive circle")
        if x - r < -1e-15 or y - r < -1e-15 or x + r > 1.0 + 1e-15 or y + r > 1.0 + 1e-15:
            raise AssertionError("circle outside unit square")

    for i in range(n):
        x1, y1, r1 = circles[i]
        for j in range(i + 1, n):
            x2, y2, r2 = circles[j]
            dx = x1 - x2
            dy = y1 - y2
            if dx * dx + dy * dy < (r1 + r2) * (r1 + r2) - 1e-15:
                raise AssertionError("overlapping circles")

    return circles


def pack_circles(n: int = 26) -> Iterable[Tuple[float, float, float]]:
    if n <= 0:
        raise ValueError("n must be a positive integer")

    if n == 1:
        return [(0.5, 0.5, 0.5)]

    if n == 2:
        circles = [(0.25, 0.5, 0.25), (0.75, 0.5, 0.25)]
        return _validate(circles, n)

    best = _best_hex_packing(n)
    grid = _grid_packing(n)

    if not best:
        circles = grid
    else:
        sum_best = best[0][2] * len(best)
        sum_grid = grid[0][2] * len(grid)
        circles = best if sum_best >= sum_grid else grid

    return _validate(circles, n)
